package local.bbsgeoimporter;
import com.google.gson.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import java.nio.file.*;import java.util.*;import java.util.jar.*;
public final class ApiLinkAudit {
 record Symbol(String owner,String name,String desc,boolean field){}
 static final Map<String,ClassNode> classes=new HashMap<>();static final List<JarFile> libraries=new ArrayList<>();
 static ClassNode lookup(String name){ClassNode c=classes.get(name);if(c!=null)return c;for(JarFile jar:libraries){var e=jar.getJarEntry(name+".class");if(e!=null)try{c=new ClassNode();new ClassReader(jar.getInputStream(e)).accept(c,ClassReader.SKIP_CODE|ClassReader.SKIP_DEBUG|ClassReader.SKIP_FRAMES);classes.put(name,c);return c;}catch(Exception ignored){}}return null;}
 static boolean exists(Symbol s,Set<String> seen){if(!seen.add(s.owner()))return false;ClassNode c=lookup(s.owner());if(c==null)return false;if(s.field()?c.fields.stream().anyMatch(f->f.name.equals(s.name())&&f.desc.equals(s.desc())):c.methods.stream().anyMatch(m->m.name.equals(s.name())&&m.desc.equals(s.desc())))return true;if(s.name().equals("<init>"))return false;if(c.superName!=null&&exists(new Symbol(c.superName,s.name(),s.desc(),s.field()),seen))return true;for(String i:c.interfaces)if(exists(new Symbol(i,s.name(),s.desc(),s.field()),seen))return true;return false;}
 public static void main(String[] args)throws Exception{libraries.add(new JarFile("E:/我的世界/.minecraft/libraries/net/minecraftforge/forge/1.20.1-47.4.28/forge-1.20.1-47.4.28-client.jar"));try(var walk=Files.walk(Path.of("E:/我的世界/.minecraft/libraries"))){for(Path p:walk.filter(p->p.toString().endsWith(".jar")&&(p.toString().contains("client-1.20.1")||p.toString().contains("eventbus")||p.toString().contains("forge-1.20.1"))).toList())libraries.add(new JarFile(p.toFile()));}var manifest=JsonParser.parseString(Files.readString(Path.of(args[0]))).getAsJsonArray();Map<String,List<ClassNode>> inputs=new LinkedHashMap<>();Set<String> paths=new HashSet<>();for(var value:manifest){var row=value.getAsJsonObject();String path=row.get("jar").getAsString();if(!paths.add(path))continue;List<ClassNode> nodes=new ArrayList<>();try(JarFile jar=new JarFile(path)){for(var item:Collections.list(jar.entries()))if(item.getName().endsWith(".class")){ClassNode c=new ClassNode();try{new ClassReader(jar.getInputStream(item)).accept(c,ClassReader.SKIP_DEBUG|ClassReader.SKIP_FRAMES);nodes.add(c);classes.put(c.name,c);}catch(Exception e){}}}inputs.put(row.get("id").getAsString(),nodes);}
 JsonObject result=new JsonObject();for(var input:inputs.entrySet()){Set<String> missing=new TreeSet<>();int[] refs={0};for(ClassNode c:input.getValue()){if(c.superName!=null&&c.superName.startsWith("io/redspace/")&&!classes.containsKey(c.superName))missing.add("class "+c.superName+" <- "+c.name);for(MethodNode m:c.methods)for(var in:m.instructions){Symbol symbol=null;if(in instanceof MethodInsnNode call)symbol=new Symbol(call.owner,call.name,call.desc,false);if(in instanceof FieldInsnNode call)symbol=new Symbol(call.owner,call.name,call.desc,true);if(symbol!=null&&symbol.owner().startsWith("io/redspace/")&&!input.getKey().equals("irons_spellbooks")&&!input.getKey().equals("irons_lib")){refs[0]++;if(!exists(symbol,new HashSet<>()))missing.add(symbol.toString()+" <- "+c.name+"#"+m.name);}}}if(refs[0]>0||!missing.isEmpty()){JsonObject row=new JsonObject();row.addProperty("references",refs[0]);row.add("missing",new Gson().toJsonTree(missing));result.add(input.getKey(),row);}}Files.writeString(Path.of(args[1]),new GsonBuilder().setPrettyPrinting().create().toJson(result));for(var e:result.entrySet())System.out.println(e.getKey()+" refs="+e.getValue().getAsJsonObject().get("references")+" missing="+e.getValue().getAsJsonObject().getAsJsonArray("missing").size());}
}
